const $=s=>document.querySelector(s), esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let meta, map, markers, selected, offset=0, publishedOffset=0, votingOffset=0;
const fmt=t=>!t?'Unavailable':/^\d{4}-\d{2}-\d{2}$/.test(t)?new Date(`${t}T00:00:00Z`).toLocaleDateString(undefined,{dateStyle:'medium',timeZone:'UTC'}):new Date(t).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
const short=t=>t?new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Unknown';
const link=(url,label)=>url&&/^https:\/\//.test(url)?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:esc(label);
async function get(url){const r=await fetch(url);if(!r.ok)throw Error('HTTP '+r.status);return r.json()}
function view(name){document.querySelectorAll('.view').forEach(x=>x.classList.add('hidden'));$('#view-'+name).classList.remove('hidden');document.querySelectorAll('.rail-item').forEach(x=>x.classList.toggle('active',x.dataset.view===name));const titles={overview:['Operational overview','A source-backed view of venue locations and public operational conditions.'],venues:['Venue registry','Explore public venue records and query conditions at a selected location.'],published:['NFL games & events','2026 NFL games at US venues, with source links and public conditions.'],voting:['Voting locations','Selected official NY, DC, MD, PA, NC, WA, SC, WV, DE, FL, CT and NJ voting records with source dates and verification status.'],events:['Event register','Sourced event records entered by an analyst for local evaluation.'],cases:['Case workbench','Internal, source-backed assessment records with separate human review.'],sources:['Sources & coverage','Connected feeds, provenance, and known gaps for this release.']};$('#page-title').textContent=titles[name][0];$('#page-subtitle').textContent=titles[name][1];$('#crumb').textContent=titles[name][0];if(name==='overview')setTimeout(()=>map?.invalidateSize(),50);if(name==='venues'&&!$('#venue-list').children.length)search();if(name==='events')loadEvents();if(name==='cases')loadCases();if(name==='published')loadPublished();if(name==='voting')loadVoting();if(name==='sources')loadChanges()}
function sourceCards(){const cards=[{title:'Venue registry',label:'WIKIDATA SNAPSHOT',text:meta.coverageNote,url:'https://query.wikidata.org/',details:[`Retrieved ${fmt(meta.retrievedAt)}`,`${meta.count.toLocaleString()} deduplicated coordinate-bearing records`,'Fields vary by source entry; capacity and address may be absent','Community-maintained data; verify venue existence and current name']},...Object.entries(meta.feeds).map(([id,s])=>({title:s.name,label:'PUBLIC LIVE CONNECTOR',text:s.scope,url:s.url,details:[`Refresh interval: ${s.refreshMinutes} minutes`,`Use: ${s.license}`,'Freshness and failures shown at query time']})),...meta.publishedEvents.sources.map(s=>({title:s.name,label:s.status==='ok'?'PUBLISHED EVENT SNAPSHOT':'SOURCE UNAVAILABLE',text:`${s.records||0} normalized records · ${s.status}`,url:s.dataset,details:[`Retrieved ${fmt(s.retrievedAt)}`,'Published schedule may change; verify before action',s.error||'Events linked to source-derived places']})),...meta.voting.sources.map(x=>({title:x.name,label:x.status==='ok'?'OFFICIAL VOTING SITE SNAPSHOT':'VOTING SOURCE UNAVAILABLE',text:`${x.coverageNote} · ${x.status}`,url:x.dataset,details:[`${x.records.toLocaleString()} location records`,`Retrieved ${fmt(x.retrievedAt)}`,`Source data edited ${fmt(x.dataEditedAt)}`,x.error||'Election assignments and hours require current official confirmation']})),{title:'Published website DNS',label:'PASSIVE OBSERVATION',text:meta.dns.caution,url:'https://www.wikidata.org/',details:[`${meta.dns.hostCount.toLocaleString()} hostnames checked`,`Observed ${fmt(meta.dns.observedAt)}`,'No ownership or venue infrastructure attribution']}];$('#source-cards').innerHTML=cards.map(c=>`<div class="panel source-card"><span class="section-kicker">${esc(c.label)}</span><h2>${esc(c.title)}</h2><p>${esc(c.text)}</p><ul>${c.details.map(d=>`<li>${esc(d)}</li>`).join('')}</ul>${link(c.url,'Open source')}</div>`).join('')}
async function loadChanges(){try{const d=await get('/api/changes?limit=25');const stale=d.snapshots.flatMap(x=>x.retainedSources.map(id=>`${x.name}: ${id}`));$('#source-changes').innerHTML=`<p>${d.total.toLocaleString()} changes in the latest comparison. ${stale.length?'Stale retained sources: '+esc(stale.join(', ')):'No retained source failures reported.'}</p>${d.items.length?d.items.map(x=>`<div class="feed-item"><strong>${esc(x.kind.replaceAll('_',' '))}: ${esc(x.after?.title||x.before?.title||x.eventId)}</strong><small>${esc(x.sourceId)} · ${esc(x.before?.startsAtLocal||'—')} → ${esc(x.after?.startsAtLocal||'—')}${x.changedFields?.length?' · fields: '+esc(x.changedFields.join(', ')):''}</small></div>`).join(''):'<p>No event changes recorded in the latest comparison.</p>'}<p>${esc(d.caution)}</p>`}catch(e){$('#source-changes').textContent='Change feed unavailable: '+e.message}try{const d=await get('/api/voting-changes?limit=25');$('#source-voting-changes').innerHTML=`<p>${d.total.toLocaleString()} voting-site changes in the latest comparison (generated ${fmt(d.generatedAt)}). ${d.retainedSources.length?'Stale retained sources: '+esc(d.retainedSources.join(', ')):'All connected voting sources reported usable data.'}</p>${d.items.length?d.items.map(x=>`<div class="feed-item"><strong>${esc(x.kind.replaceAll('_',' '))}: ${esc(x.after?.name||x.before?.name||x.siteId)}</strong><small>${esc(x.sourceId)}${x.changedFields?.length?' · fields: '+esc(x.changedFields.join(', ')):''}</small></div>`).join(''):'<p>No voting-site changes recorded in the latest comparison.</p>'}<p>${esc(d.caution)}</p>`}catch(e){$('#source-voting-changes').textContent='Voting change feed unavailable: '+e.message}try{const h=await get('/api/voting-history?limit=5');$('#source-voting-history').innerHTML=`<p>${h.total.toLocaleString()} saved run${h.total===1?'':'s'} · archive checks passed</p>${h.items.map(run=>`<div class="feed-item"><strong>${fmt(run.archivedAt)} · ${run.recordCount.toLocaleString()} rows</strong><small>${run.sourceCount} sources · ${run.changeCount} changes${run.retainedSources.length?' · retained: '+esc(run.retainedSources.join(', ')):''}${run.backfilled?' · backfilled archive':''} · SHA-256 ${esc(run.archiveHash.slice(0,12))}…</small></div>`).join('')||'<p>No voting runs archived yet.</p>'}<p>${esc(h.caution)}</p>`}catch(e){$('#source-voting-history').textContent='Voting history unavailable: '+e.message}}
async function init(){try{meta=await get('/api/meta');$('#metric-venues').textContent=meta.count.toLocaleString();$('#metric-events').textContent=meta.publishedEvents.count.toLocaleString();$('#metric-voting').textContent=meta.voting.count.toLocaleString();$('#metric-types').textContent=meta.types.filter(t=>t!=='fairground'&&t!=='racetrack').length;$('#map-total').textContent=meta.count.toLocaleString();$('#snapshot-date').textContent=short(meta.retrievedAt);$('#venue-type').innerHTML+=[...meta.types].filter(t=>!['fairground','racetrack'].includes(t)).map(t=>`<option value="${esc(t)}">${esc(t[0].toUpperCase()+t.slice(1))}</option>`).join('');sourceCards();$('#published-source').innerHTML+=meta.publishedEvents.sources.filter(x=>x.records).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');$('#published-source').value='nfl';await initMap()}catch(e){$('#metric-venues').textContent='Error';console.error(e)}}
async function initMap(){if(!window.L){$('#map').textContent='Map library unavailable. Registry search remains available.';return}map=L.map('map',{zoomControl:false,preferCanvas:true}).setView([39,-97],4);L.control.zoom({position:'topright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:18}).addTo(map);const data=await get('/api/map');markers=L.layerGroup().addTo(map);for(const v of data.items){const color=['stadium','arena'].includes(v.type)?'#5bd1d4':'#e3b96f';L.circleMarker([v.lat,v.lon],{radius:4,color,fillColor:color,fillOpacity:.68,weight:1}).addTo(markers).bindPopup(`<strong>${esc(v.name)}</strong><br>${esc(v.type)}<br>${link(v.source,'Wikidata source')}`)}if(data.total>data.items.length){const note=L.control({position:'bottomright'});note.onAdd=()=>{const d=L.DomUtil.create('div');d.style='background:#0c1d27;color:#d4edf1;padding:7px 10px;font-size:11px;border-radius:4px';d.textContent='Map preview sampled from registry. Search for full records.';return d};note.addTo(map)}}
async function search(reset=false){if(reset)offset=0;const q=$('#venue-search').value.trim(),type=$('#venue-type').value;$('#venue-list').innerHTML='<div class="empty-state" style="margin:50px">Searching…</div>';try{const r=await get(`/api/venues?q=${encodeURIComponent(q)}&type=${encodeURIComponent(type)}&limit=100&offset=${offset}`);$('#result-count').textContent=`${r.total.toLocaleString()} matching records`;$('#result-page').textContent=r.total?`Showing ${offset+1}–${Math.min(offset+100,r.total)}`:'No results';$('#prev-page').disabled=offset===0;$('#next-page').disabled=offset+100>=r.total;$('#venue-list').innerHTML=r.items.length?r.items.map(v=>`<button class="venue-item ${selected===v.id?'selected':''}" data-id="${esc(v.id)}"><span class="type">${esc(v.type)}</span><strong>${esc(v.name)}</strong><small>${esc([v.city,v.region].filter(Boolean).join(', ')||'Location from coordinates')} · ${v.lat.toFixed(3)}, ${v.lon.toFixed(3)}</small></button>`).join(''):'<div class="empty-state" style="margin:70px"><p>No matching venues in this snapshot.</p></div>';document.querySelectorAll('.venue-item').forEach(x=>x.onclick=()=>detail(x.dataset.id))}catch(e){$('#venue-list').textContent='Search failed: '+e.message}}
function feedStatus(f){if(f.error==='No source coordinates')return 'Not queried · no source coordinates';return f.error?`<span style="color:#e9ba78">${f.stale?'STALE / UNAVAILABLE':'ERROR'} · ${esc(f.error)}</span>`:`Retrieved ${fmt(f.retrievedAt)}`}
async function detail(id){selected=id;document.querySelectorAll('.venue-item').forEach(x=>x.classList.toggle('selected',x.dataset.id===id));$('#venue-detail').innerHTML='<div class="empty-state"><p>Querying public feeds for this venue…</p></div>';try{const d=await get('/api/venue/'+encodeURIComponent(id)),v=d.venue;$('#venue-detail').innerHTML=`<div class="detail-top"><div><span class="section-kicker">VENUE RECORD · ${esc(v.id)}</span><h2>${esc(v.name)}</h2><p>${esc(v.type)} · ${esc([v.city,v.region].filter(Boolean).join(', ')||'City not available')}</p></div><span class="data-tag">SOURCE RECORD</span></div><div class="detail-grid"><div class="fact"><span>COORDINATES</span><strong>${v.lat.toFixed(5)}, ${v.lon.toFixed(5)}</strong></div><div class="fact"><span>CAPACITY</span><strong>${v.capacity?Number(v.capacity).toLocaleString():'Not sourced'}</strong></div><div class="fact"><span>ADDRESS</span><strong>${esc([v.street,v.postal].filter(Boolean).join(' · ')||'Not sourced')}</strong></div></div><div class="detail-section"><h3>Provenance</h3><p>Community-maintained venue record. Verify current venue name, footprint, schedule, and operator before operational use.</p>${link(v.source,'Open Wikidata record')}${v.website?' · '+link(v.website,'Venue website'):''}</div><div class="detail-section"><h3>Published website DNS</h3>${d.dns?`<p>Hostname: ${esc(d.dns.hostname)} · Observed ${fmt(d.dns.observedAt)}. These addresses may belong to a CDN or third party; venue ownership is unverified.</p><p>Public A records: ${d.dns.addresses.length?d.dns.addresses.map(esc).join(', '):'None resolved'}${d.dns.cname.length?' · CNAME: '+d.dns.cname.map(esc).join(', '):''}</p>`:'<p>No published website hostname in the venue snapshot.</p>'}</div><div class="detail-section"><div class="feed-head"><h3>NWS point alerts</h3><span class="feed-meta">${feedStatus(d.weather)}</span></div>${d.weather.items.length?d.weather.items.map(a=>`<div class="feed-item"><strong>${esc(a.event||a.headline)}</strong><small>${esc(a.severity||'Unknown severity')} · Expires ${fmt(a.expires)} · ${link(a.url,'NWS alert')}</small></div>`).join(''):'<p>No active alerts returned for this point. This does not establish absence of hazards.</p>'}</div><div class="detail-section"><div class="feed-head"><h3>USGS recent earthquakes</h3><span class="feed-meta">${feedStatus(d.earthquakes)}</span></div><p>Observations within 250 km; proximity does not imply venue impact.</p>${d.earthquakes.items.length?d.earthquakes.items.slice(0,5).map(e=>`<div class="feed-item"><strong>${esc(e.title)}</strong><small>${fmt(e.time)} · ${link(e.url,'USGS record')}</small></div>`).join(''):'<p>No nearby events in the selected feed window.</p>'}</div><div class="detail-section"><div class="feed-head"><h3>NASA natural events</h3><span class="feed-meta">${feedStatus(d.naturalEvents)}</span></div><p>Open EONET event points within 250 km; proximity does not establish local impact.</p>${d.naturalEvents.items.slice(0,5).map(n=>`<div class="feed-item"><strong>${esc(n.title)}</strong><small>${esc(n.category)} · ${link(n.url,'NASA source')}</small></div>`).join('')||'<p>No nearby open events returned.</p>'}</div><div class="detail-section"><div class="feed-head"><h3>CISA KEV watchlist</h3><span class="feed-meta">${feedStatus(d.kev)}</span></div><p>Latest catalog entries are <strong>not linked to this venue</strong>. A verified asset inventory is required for correlation.</p>${d.kev.items.slice(0,3).map(k=>`<div class="feed-item"><strong>${esc(k.cve)} · ${esc(k.vendor)} ${esc(k.product)}</strong><small>Added ${esc(k.added)} · ${link('https://www.cisa.gov/known-exploited-vulnerabilities-catalog','CISA catalog')}</small></div>`).join('')}</div>`}catch(e){$('#venue-detail').innerHTML=`<div class="empty-state"><p>Could not load venue context: ${esc(e.message)}</p></div>`}}
const localTime=e=>e.timeTbd?esc(new Date(e.startsAtLocal).toLocaleDateString(undefined,{dateStyle:'medium',timeZone:'America/New_York'}))+' · Kickoff time TBD':esc(String(e.startsAtLocal||'').replace('T',' ').replace('.000',''))+' · '+esc(e.timeZone||'timezone unverified');
async function loadPublished(reset=false){if(reset)publishedOffset=0, votingOffset=0;const q=$('#published-search').value.trim(),source=$('#published-source').value;$('#published-list').innerHTML='<div class="event-empty">Loading published events…</div>';try{const d=await get(`/api/public-events?q=${encodeURIComponent(q)}&source=${encodeURIComponent(source)}&limit=50&offset=${publishedOffset}`);$('#published-count').textContent=`${d.total.toLocaleString()} published-source events`;$('#published-page').textContent=d.total?`Showing ${publishedOffset+1}–${Math.min(publishedOffset+50,d.total)}`:'No results';$('#published-prev').disabled=publishedOffset===0;$('#published-next').disabled=publishedOffset+50>=d.total;$('#published-list').innerHTML=d.items.length?d.items.map(e=>`<button class="venue-item published-item" data-id="${esc(e.id)}"><span class="published-source-tag">${esc(e.sourceId)}${e.status.startsWith('cancelled')?' · CANCELLED':''}</span><strong>${esc(e.title)}</strong><small>${localTime(e)}<br>${esc(e.sourcePlace.name||'Place not named')}</small></button>`).join(''):'<div class="event-empty">No matching published events.</div>';document.querySelectorAll('.published-item').forEach(x=>x.onclick=()=>publishedDetail(x.dataset.id))}catch(e){$('#published-list').textContent='Feed snapshot unavailable: '+e.message}}
function briefHtml(b){if(!b)return '';return `<div class="detail-section brief-panel"><div class="feed-head"><h3>Event situation picture</h3><span class="feed-meta">Generated ${fmt(b.generatedAt)}</span></div><p>${esc(b.interpretation)}</p><div class="brief-status"><span>SEVERITY: ${esc(b.assessment.severity)}</span><span>CONFIDENCE: ${esc(b.assessment.confidence)}</span></div><h4>Analyst review candidates</h4>${b.reviewCandidates.length?b.reviewCandidates.map(x=>`<div class="feed-item"><strong>${esc(x.reason)}</strong><small>${esc(x.action)} · ${esc(x.status)}</small></div>`).join(''):'<p>No deterministic review candidate from the connected feeds. This does not establish that the event has no threat.</p>'}<h4>Source observations</h4>${b.observations.length?b.observations.map(x=>`<div class="feed-item"><strong>${esc(x.source.toUpperCase())} · ${esc(x.title)}</strong><small>${esc(x.qualifier)} · ${link(x.url,'Source record')}</small></div>`).join(''):'<p>No observations returned by the connected point feeds.</p>'}<h4>Coverage and unresolved facts</h4><ul>${b.gaps.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>Feed state: NWS ${esc(b.feeds.nws.state)} · USGS ${esc(b.feeds.usgs.state)} · NASA ${esc(b.feeds.nasaEonet.state)}.</p></div>`}
function forecastHtml(f){if(!f)return '';return `<div class="detail-section"><div class="feed-head"><h3>NWS kickoff-hour forecast</h3><span class="feed-meta">${esc(f.status.toUpperCase())}</span></div>${f.status==='ok'||f.status==='stale'?`<p>${esc(f.shortForecast||'No summary')} · ${esc(f.temperature)}°${esc(f.temperatureUnit)} · Wind ${esc(f.windSpeed||'unknown')} ${esc(f.windDirection||'')}</p><p>Precipitation probability: ${f.probabilityOfPrecipitation==null?'not supplied':esc(f.probabilityOfPrecipitation)+'%'} · Hour ${fmt(f.startTime)} · Retrieved ${fmt(f.retrievedAt)} · ${link(f.url,'NWS forecast')}</p><p>Point forecast; verify conditions and venue exposure close to kickoff.</p>`:`<p>${esc(f.reason||'Forecast unavailable')}</p>`}</div>`}
async function publishedDetail(id){$('#published-detail').innerHTML='<div class="event-empty">Querying source and public conditions…</div>';try{const d=await get('/api/public-event/'+encodeURIComponent(id)),e=d.event,p=d.place,c=d.conditions;$('#published-detail').innerHTML=`<div class="detail-top"><div><span class="section-kicker">PUBLISHED EVENT · ${esc(e.sourceId)}</span><h2>${esc(e.title)}</h2><p>${localTime(e)}</p></div><span class="data-tag">${esc(e.status.toUpperCase())}</span></div><div class="source-note">Calendar publication is evidence of a listed event, not confirmation that it will occur unchanged. Verify with the publisher before protective action.</div><div class="event-info-grid"><div class="fact"><span>END</span><strong>${esc(e.endsAtLocal||'Not sourced')} ${esc(e.timeZone)}</strong></div><div class="fact"><span>ORGANIZER</span><strong>${esc(e.organizer)}</strong></div><div class="fact"><span>CATEGORY</span><strong>${esc(e.category||'Not sourced')}</strong></div><div class="fact"><span>SOURCE PLACE</span><strong>${esc(p?.name||'Not sourced')}</strong></div><div class="fact"><span>LOCATION DETAIL</span><strong>${esc(p?.address||'Not sourced')}</strong></div><div class="fact"><span>COORDINATES</span><strong>${Number.isFinite(p?.lat)?p.lat.toFixed(5)+', '+p.lon.toFixed(5):'Not sourced'}${p?.coordinateSource?' · '+esc(p.coordinateSource):''}</strong></div></div><div class="detail-section"><h3>Source and place linkage</h3><p>Event source ID: ${esc(e.id)}<br>Place record: ${esc(e.placeId||'Unlinked')}<br>Wikidata venue match: ${esc(e.venueId||'None; no attribution inferred')} · ${esc(e.venueLinkStatus||'No exact/proximate match')}<br>Retrieved ${fmt(e.retrievedAt)}</p>${link(e.sourceUrl,e.sourceId==='nfl'?'ESPN game listing':'Official event listing')} · ${link(e.sourceDataset,'Publisher dataset')}<p><button class="text-button" data-case-type="published_event" data-case-id="${esc(e.id)}">Open internal case ↗</button></p></div>${e.participants?.length?`<div class="detail-section"><h3>Participating organizations</h3><p>${e.participants.map(x=>`${esc(x.name)} (${esc(x.role)})`).join(' · ')}</p><p>Team schedule participation does not verify an individual person's attendance.</p></div>`:''}${e.description?`<div class="detail-section"><h3>Published description</h3><div class="event-description">${esc(e.description)}</div></div>`:''}${briefHtml(d.brief)}${forecastHtml(d.forecast)}${c?`<div class="detail-section"><div class="feed-head"><h3>NWS point alerts</h3><span class="feed-meta">${feedStatus(c.weather)}</span></div>${c.weather.items.length?c.weather.items.map(a=>`<div class="feed-item"><strong>${esc(a.event||a.headline)}</strong><small>${esc(a.severity||'Unknown')} · ${link(a.url,'NWS source')}</small></div>`).join(''):'<p>No active alert returned for this coordinate.</p>'}</div><div class="detail-section"><div class="feed-head"><h3>USGS nearby observations</h3><span class="feed-meta">${feedStatus(c.earthquakes)}</span></div><p>Within 250 km; proximity alone does not establish impact.</p>${c.earthquakes.items.slice(0,3).map(x=>`<div class="feed-item"><strong>${esc(x.title)}</strong><small>${link(x.url,'USGS source')}</small></div>`).join('')||'<p>No nearby observations in this feed window.</p>'}</div><div class="detail-section"><div class="feed-head"><h3>NASA natural events</h3><span class="feed-meta">${feedStatus(c.naturalEvents)}</span></div><p>Open event points within 250 km; proximity does not establish impact.</p>${c.naturalEvents.items.slice(0,3).map(n=>`<div class="feed-item"><strong>${esc(n.title)}</strong><small>${link(n.url,'NASA source')}</small></div>`).join('')||'<p>No nearby open events returned.</p>'}</div>`:''}`;}catch(err){$('#published-detail').innerHTML=`<div class="event-empty">Could not load event: ${esc(err.message)}</div>`}}
const votingType={election_day_polling_place:'Election Day polling place',election_day_vote_center:'Election Day vote center',early_vote_center:'Early vote center',voting_center:'Voting center',ballot_drop_box:'Mail-ballot drop box',secure_ballot_intake_station:'Secure ballot intake station'};
async function loadVoting(reset=false){if(reset)votingOffset=0;const q=$('#voting-search').value.trim(),state=$('#voting-state').value,type=$('#voting-type').value;$('#voting-list').innerHTML='<div class="event-empty">Loading voting sites…</div>';try{const d=await get(`/api/voting-locations?q=${encodeURIComponent(q)}&state=${encodeURIComponent(state)}&type=${encodeURIComponent(type)}&limit=50&offset=${votingOffset}`);$('#voting-count').textContent=`${d.total.toLocaleString()} source records${d.staleCount?' · '+d.staleCount.toLocaleString()+' stale':''}`;$('#voting-page').textContent=d.total?`Showing ${votingOffset+1}–${Math.min(votingOffset+50,d.total)}`:'No results';$('#voting-prev').disabled=votingOffset===0;$('#voting-next').disabled=votingOffset+50>=d.total;$('#voting-list').innerHTML=d.items.length?d.items.map(v=>`<button class="venue-item voting-item" data-id="${esc(v.id)}"><span class="type">${esc(votingType[v.type]||v.type)} · ${esc(v.jurisdiction)}${v.connectorStatus!=='ok'?' · STALE SOURCE':''}</span><strong>${esc(v.name)}</strong><small>${esc([v.street,v.city,v.county].filter(Boolean).join(', '))}</small></button>`).join(''):'<div class="event-empty">No matching voting sites in the connected jurisdictions.</div>';document.querySelectorAll('.voting-item').forEach(x=>x.onclick=()=>votingDetail(x.dataset.id))}catch(e){$('#voting-list').textContent='Voting snapshot unavailable: '+e.message}}
async function votingDetail(id){$('#voting-detail').innerHTML='<div class="event-empty">Loading official site record and public conditions…</div>';try{const d=await get('/api/voting-location/'+encodeURIComponent(id)),v=d.location,c=d.conditions||{weather:{items:[],error:'No source coordinates',stale:true},earthquakes:{items:[],error:'No source coordinates',stale:true},naturalEvents:{items:[],error:'No source coordinates',stale:true}},hasPoint=Number.isFinite(v.lat)&&Number.isFinite(v.lon);$('#voting-detail').innerHTML=`<div class="detail-top"><div><span class="section-kicker">VOTING SITE · ${esc(v.jurisdiction)}</span><h2>${esc(v.name)}</h2><p>${esc(votingType[v.type]||v.type)}</p></div><span class="data-tag">${esc(v.status.toUpperCase())}</span></div><div class="source-note">Connector: ${esc(d.source?.status||'unknown')} · ${esc(v.sourceDataStatus)}<br>This record is not a voter assignment or a guarantee of current operation.</div><div class="event-info-grid"><div class="fact"><span>ADDRESS</span><strong>${esc(['WA','SC','WV','DE','FL','CT','NJ'].includes(v.jurisdiction)&&!v.city?v.street:[v.street,v.addressLine2,v.city,v.jurisdiction,v.postal].filter(Boolean).join(', '))}</strong></div><div class="fact"><span>DATES OPEN</span><strong>${v.schedule?.length?'See published schedule below':esc(v.datesOpen||'Not supplied by source')}</strong></div><div class="fact"><span>HOURS</span><strong>${v.schedule?.length?'See published schedule below':esc(v.hours||'Not supplied by source')}</strong></div><div class="fact"><span>VOTING SPACE</span><strong>${esc(v.votingSpace||'Not supplied')}</strong></div><div class="fact"><span>ACCESSIBILITY</span><strong>${esc(v.accessibility||'Not supplied')}</strong></div>${v.facilityClass?`<div class="fact"><span>FACILITY CLASS</span><strong>${esc(v.facilityClass)}</strong></div>`:''}${v.secureBallotIntakePublished?`<div class="fact"><span>BALLOT INTAKE</span><strong>${esc(v.secureBallotIntakePublished)}</strong></div>`:''}${v.timeZone?`<div class="fact"><span>TIME ZONE</span><strong>${esc(v.timeZone)}</strong></div>`:''}${v.siteCategory?`<div class="fact"><span>SITE CATEGORY</span><strong>${esc(v.siteCategory)}</strong></div>`:''}${v.contactPhone?`<div class="fact"><span>COUNTY CONTACT</span><strong>${esc(v.contactPhone)}</strong></div>`:''}<div class="fact"><span>COORDINATES</span><strong>${hasPoint?v.lat.toFixed(5)+', '+v.lon.toFixed(5):'Not published; conditions not queried'}</strong></div>${v.precinct?`<div class="fact"><span>PRECINCT</span><strong>${esc(v.precinct)}${v.precinctCode?' · '+esc(v.precinctCode):''}</strong></div>`:''}${v.geocodeMatchScore!==undefined?`<div class="fact"><span>POINT QUALITY</span><strong>${esc(v.geocodeMatchStatus||'Not supplied')} · score ${esc(v.geocodeMatchScore??'Not supplied')} · estimated, verify entrance</strong></div>`:''}</div>${v.schedule?.length?`<div class="detail-section"><h3>Published schedule</h3>${v.schedule.map(item=>`<p>${esc(item.dates)} · ${esc(item.hours)}</p>`).join('')}</div>`:''}${v.description?`<div class="detail-section"><h3>Publisher site note</h3><p>${esc(v.description.replace(/([.!?])(?=[A-Z])/g,'$1 '))}</p></div>`:''}${v.sourceScheduleAnomalies?.length?`<div class="detail-section"><h3>Publisher schedule anomalies</h3>${v.sourceScheduleAnomalies.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:''}<div class="detail-section"><h3>Official source</h3><p>Record ${esc(v.sourceRecordId)}${v.sourceFile?` · ${esc(v.sourceFile)}${v.sourcePage?` page ${esc(v.sourcePage)}`:''}`:''} · Retrieved ${fmt(v.retrievedAt)}${v.sourceEditedAt?' · Source edited '+fmt(v.sourceEditedAt):''}</p>${link(v.sourceRecordUrl,'Source record')} · ${link(v.sourceUrl,'Dataset')}<p><button class="text-button" data-case-type="voting_site" data-case-id="${esc(v.id)}">Open internal case ↗</button></p></div><div class="detail-section"><div class="feed-head"><h3>NWS point alerts</h3><span class="feed-meta">${feedStatus(c.weather)}</span></div>${c.weather.items.length?c.weather.items.slice(0,5).map(a=>`<div class="feed-item"><strong>${esc(a.event||a.headline)}</strong><small>${link(a.url,'NWS alert')}</small></div>`).join(''):hasPoint?'<p>No active alert returned for this point.</p>':'<p>Not queried; source has no coordinates.</p>'}</div><div class="detail-section"><div class="feed-head"><h3>USGS nearby observations</h3><span class="feed-meta">${feedStatus(c.earthquakes)}</span></div><p>Within 250 km; proximity does not establish site impact.</p>${c.earthquakes.items.slice(0,3).map(x=>`<div class="feed-item"><strong>${esc(x.title)}</strong><small>${link(x.url,'USGS source')}</small></div>`).join('')||(hasPoint?'<p>No nearby observations in this feed window.</p>':'<p>Not queried; source has no coordinates.</p>')}</div><div class="detail-section"><div class="feed-head"><h3>NASA natural events</h3><span class="feed-meta">${feedStatus(c.naturalEvents)}</span></div><p>Within 250 km; proximity does not establish site impact.</p>${c.naturalEvents.items.slice(0,3).map(x=>`<div class="feed-item"><strong>${esc(x.title)}</strong><small>${link(x.url,'NASA source')}</small></div>`).join('')||(hasPoint?'<p>No nearby open events returned.</p>':'<p>Not queried; source has no coordinates.</p>')}</div>`}catch(e){$('#voting-detail').innerHTML=`<div class="event-empty">Could not load voting site: ${esc(e.message)}</div>`}}
let operatorToken=null,currentOperator=null,selectedCaseId=null;
async function operatorRequest(url,options={}){const headers={...(options.headers||{}),Authorization:`Bearer ${operatorToken||''}`};const response=await fetch(url,{...options,headers});const body=await response.json();if(!response.ok)throw Error(body.error||`HTTP ${response.status}`);return body}
async function unlockOperator(inputId){const token=$(inputId).value.trim();$(inputId).value='';if(!/^[a-f0-9]{64}$/.test(token)){$('#operator-state').textContent='Enter a valid provisioned token.';$('#case-operator-state').textContent='Enter a valid provisioned token.';return}operatorToken=token;try{const d=await operatorRequest('/api/operators/me');currentOperator=d.operator;const label=`Unlocked as ${d.operator.name} (${d.operator.role}). Audit chain: ${d.audit.entries} entries verified locally.`;$('#operator-state').textContent=label;$('#case-operator-state').textContent=label;loadEvents();loadCases()}catch(error){operatorToken=null;currentOperator=null;$('#operator-state').textContent=error.message;$('#case-operator-state').textContent=error.message}}
$('#operator-unlock').onclick=()=>unlockOperator('#operator-token');$('#case-operator-unlock').onclick=()=>unlockOperator('#case-operator-token');
async function loadEvents(){$('#event-form').querySelectorAll('input,button').forEach(element=>{element.disabled=!operatorToken});if(!operatorToken){$('#event-list').innerHTML='<div class="event-empty">Register locked. Enter an operator token above.</div>';return}try{const d=await operatorRequest('/api/events');$('#event-list').innerHTML=d.items.length?d.items.map(e=>`<div class="event-card"><span class="chip">${esc(e.status.replaceAll('_',' ').toUpperCase())}</span><strong>${esc(e.title)}</strong><small>${fmt(e.startsAt)} · Venue ${esc(e.venueId)}</small><p>Organizer: ${esc(e.organizer||'Not sourced')} · Expected attendance: ${e.expectedAttendance==null?'Not sourced':Number(e.expectedAttendance).toLocaleString()}<br>Created by: ${esc(e.owner)} · ${link(e.sourceUrl,'Source')}</p>${e.review?`<p>Reviewer: ${esc(e.review.reviewerId)} · ${esc(e.review.rationale)}</p>`:''}${currentOperator?.role==='reviewer'&&e.status==='unreviewed'&&e.createdBy!==currentOperator.id?`<div class="review-form"><select aria-label="Review decision"><option value="accepted_for_register">Accept for register</option><option value="returned_for_correction">Return for correction</option></select><textarea aria-label="Review rationale" placeholder="Source check and rationale (at least 20 characters)" maxlength="2000"></textarea><button class="primary" data-review-id="${esc(e.id)}" type="button">Record review</button></div>`:''}</div>`).join(''):'<div class="event-empty">No analyst events entered.</div>';document.querySelectorAll('[data-review-id]').forEach(button=>button.onclick=async()=>{const area=button.closest('.review-form'),decision=area.querySelector('select').value,rationale=area.querySelector('textarea').value;try{await operatorRequest(`/api/events/${encodeURIComponent(button.dataset.reviewId)}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision,rationale})});loadEvents()}catch(error){$('#operator-state').textContent='Review failed: '+error.message}})}catch(error){$('#event-list').textContent='Event register unavailable: '+error.message}}
$('#event-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;if(!operatorToken){$('#event-message').textContent='Unlock the register first.';return}const values=Object.fromEntries(new FormData(form));values.startsAt=new Date(values.startsAt).toISOString();if(values.endsAt)values.endsAt=new Date(values.endsAt).toISOString();try{await operatorRequest('/api/events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});$('#event-message').textContent='Saved as unreviewed with operator identity and audit entry.';form.reset();loadEvents()}catch(error){$('#event-message').textContent=error.message}};

async function loadCases(){const form=$('#case-form');form.querySelectorAll('input,textarea,select,button').forEach(element=>{element.disabled=!operatorToken});if(!operatorToken){$('#case-list').innerHTML='<div class="event-empty">Workbench locked. Enter an operator token above.</div>';$('#case-detail').innerHTML='<div class="event-empty">No case selected.</div>';return}try{const d=await operatorRequest('/api/cases');$('#case-list').innerHTML=d.items.length?d.items.map(c=>`<button class="case-item" data-case-id="${esc(c.id)}"><strong>${esc(c.subject.title)} · ${esc(c.subject.type.replaceAll('_',' '))}</strong><small>${esc(c.authority)} · ${c.assessmentCount} assessments · ${fmt(c.createdAt)}</small></button>`).join(''):'<div class="event-empty">No cases opened.</div>';document.querySelectorAll('[data-case-id]').forEach(button=>button.onclick=()=>loadCase(button.dataset.caseId));if(selectedCaseId)await loadCase(selectedCaseId)}catch(error){$('#case-list').textContent='Case register unavailable: '+error.message}}
$('#case-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;if(!operatorToken){$('#case-message').textContent='Unlock the workbench first.';return}const input=Object.fromEntries(new FormData(form));try{const created=await operatorRequest('/api/cases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});selectedCaseId=created.id;$('#case-message').textContent='Internal case opened with a source snapshot and audit entry.';form.reset();await loadCases()}catch(error){$('#case-message').textContent=error.message}};
const evidenceFields=()=>`<div class="evidence-entry"><label>Citation URL<input name="url" type="url" required placeholder="https://official-source.example/item"></label><label>Source observation time<input name="observedAt" type="datetime-local" required></label><label>Claim classification<select name="classification"><option value="observation">Observation</option><option value="official_notice">Official notice</option><option value="allegation">Allegation</option><option value="analytic_context">Analytic context</option></select></label><label>Exact claim or observation<textarea name="claim" required minlength="10" maxlength="1000"></textarea></label><label>Relevance to this case<textarea name="relevance" required minlength="10" maxlength="1000"></textarea></label></div>`;
function renderCaseReviewers(caseId,caseRecord,reviewers){
  const owner=caseRecord.createdBy===currentOperator?.id;
  $('#case-detail').insertAdjacentHTML('beforeend',`<h3>Case reviewer access</h3><p>Only the case owner and active assigned reviewers can read this case. Assignments and revocations are audited.</p>${reviewers.length?reviewers.map(item=>`<div class="feed-item"><strong>${esc(item.reviewerId)} · ${item.revokedAt?'revoked':'active'}</strong><small>Assigned ${fmt(item.createdAt)} by ${esc(item.assignedBy)} · ${esc(item.rationale)}</small>${item.revokedAt?`<small>Revoked ${fmt(item.revokedAt)} by ${esc(item.revokedBy)} · ${esc(item.revocationRationale)}</small>`:owner?`<button type="button" data-revoke-reviewer="${esc(item.id)}">Revoke access</button>`:''}</div>`).join(''):'<p>No reviewer assigned.</p>'}${owner?`<form id="case-reviewer-form" class="assessment-form"><label>Existing reviewer operator ID<input name="reviewerId" required pattern="[a-z][a-z0-9_-]{2,39}"></label><label>Assignment rationale<textarea name="rationale" required minlength="20" maxlength="2000"></textarea></label><button class="primary" type="submit">Assign reviewer</button></form>`:''}<p id="case-reviewer-message"></p>`);
  const message=$('#case-reviewer-message');
  if(owner){
    $('#case-reviewer-form').onsubmit=async event=>{event.preventDefault();const input=Object.fromEntries(new FormData(event.currentTarget));try{await operatorRequest(`/api/cases/${encodeURIComponent(caseId)}/reviewers`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});await loadCase(caseId)}catch(error){message.textContent=error.message}};
    document.querySelectorAll('[data-revoke-reviewer]').forEach(button=>button.onclick=async()=>{const rationale=prompt('Reason for revoking this reviewer (at least 20 characters):');if(rationale===null)return;try{await operatorRequest(`/api/case-reviewers/${encodeURIComponent(button.dataset.revokeReviewer)}/revoke`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rationale})});await loadCase(caseId)}catch(error){message.textContent=error.message}});
  }
}
function renderPersonScopes(caseId,caseRecord,scopes){
  if(caseRecord.subject.type!=='published_event')return;
  const detail=$('#case-detail');
  detail.insertAdjacentHTML('beforeend',`<section class="assessment-record"><h3>Event-specific protected people</h3><p>Internal records only. A reviewer must approve a role scope before a name is collected. Published rosters alone do not establish a protective designation.</p><button id="download-case-brief" type="button">Download draft internal event brief (JSON)</button>${scopes.map(s=>`<div class="assessment-record"><span class="chip">${esc(s.status.toUpperCase())}${s.expired?' · EXPIRED':''}</span><strong>${esc(s.role.replaceAll('_',' '))}</strong><p>${esc(s.protectiveNexus)}<br>Authority: ${esc(s.lawfulAuthority)} · Expires ${fmt(s.expiresAt)}</p>${s.review?`<p>Reviewer ${esc(s.review.reviewerId)}: ${esc(s.review.rationale)}</p>`:''}${currentOperator?.role==='reviewer'&&s.status==='pending_review'&&s.createdBy!==currentOperator.id?`<div class="review-form"><select aria-label="Scope decision"><option value="approved">Approve scope</option><option value="rejected">Reject scope</option></select><textarea aria-label="Scope rationale" minlength="20" maxlength="2000" placeholder="Review rationale"></textarea><button type="button" data-scope-review="${esc(s.id)}">Record scope decision</button></div>`:''}${s.people.map(p=>`<div class="feed-item"><strong>${esc(p.displayName)} · ${esc(p.professionalRole)} · ${esc(p.status)}</strong><small>${esc(p.identityConfidence)} identity confidence · Retention review ${fmt(p.retentionUntil)}${p.retentionReviewDue?' · DUE':''}</small><p>Designation: ${link(p.designationSource.url,p.designationSource.authority)} · ${fmt(p.designationSource.observedAt)}<br>${esc(p.identityRationale)}</p>${p.publicProfessionalFacts.map(f=>`<p>${esc(f.claim)} · ${link(f.sourceUrl,'Source')} · ${fmt(f.observedAt)}</p>`).join('')}${p.review?`<p>Reviewer ${esc(p.review.reviewerId)}: ${esc(p.review.rationale)}</p>`:''}${currentOperator?.role==='reviewer'&&p.status==='pending_review'&&p.createdBy!==currentOperator.id?`<div class="review-form"><select aria-label="Person decision"><option value="approved">Approve person record</option><option value="rejected">Reject person record</option></select><textarea aria-label="Person rationale" minlength="20" maxlength="2000" placeholder="Review rationale"></textarea><button type="button" data-person-review="${esc(p.id)}">Record person decision</button></div>`:''}</div>`).join('')}${s.status==='approved'&&!s.expired?`<form class="person-form" data-person-scope="${esc(s.id)}"><h4>Add designated professional under this scope</h4><p>Role: ${esc(s.role.replaceAll('_',' '))}. Enter one cited public professional fact; additional facts can be entered through the local API.</p><label>Display name<input name="displayName" required minlength="2" maxlength="200"></label><label>Professional role<input name="professionalRole" required minlength="3" maxlength="200"></label><label>Designation source URL<input name="designationUrl" type="url" required></label><label>Designating authority<input name="designationAuthority" required minlength="3" maxlength="200"></label><label>Designation observed<input name="designationObservedAt" type="datetime-local" required></label><label>Identity confidence<select name="identityConfidence"><option value="low">Low</option><option value="moderate">Moderate</option><option value="high">High</option></select></label><label>Identity basis<textarea name="identityRationale" required minlength="20" maxlength="1000"></textarea></label><label>Public professional fact<textarea name="factClaim" required minlength="10" maxlength="500"></textarea></label><label>Fact source URL<input name="factUrl" type="url" required></label><label>Fact observed<input name="factObservedAt" type="datetime-local" required></label><label>Retention review date<input name="retentionUntil" type="datetime-local" required></label><button type="submit">Save pending person record</button></form>`:''}</div>`).join('')||'<p>No role scopes requested.</p>'}<form id="person-scope-form"><h4>Request a role scope</h4><label>Protected role<select name="role"><option value="team_official">Team official</option><option value="player">Player</option><option value="coach">Coach</option><option value="league_official">League official</option><option value="elected_official">Elected official</option><option value="performer">Performer</option><option value="other_designated">Other designated</option></select></label><label>Event-specific protective nexus<textarea name="protectiveNexus" required minlength="30" maxlength="2000"></textarea></label><label>Lawful authority<textarea name="lawfulAuthority" required minlength="10" maxlength="500"></textarea></label><label>Collection purpose<textarea name="collectionPurpose" required minlength="20" maxlength="500"></textarea></label><label>Scope expiry (within 90 days)<input name="expiresAt" type="datetime-local" required></label><button type="submit">Request reviewer approval</button></form><p id="person-scope-message"></p></section>`);
  $('#download-case-brief').onclick=async()=>{const message=$('#person-scope-message');message.textContent='Building draft internal brief…';try{const brief=await operatorRequest(`/api/cases/${encodeURIComponent(caseId)}/brief`),blob=new Blob([JSON.stringify(brief,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`event-atlas-case-${caseId}-draft.json`;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);message.textContent='Draft downloaded locally. Review source freshness and approval gates before use.'}catch(error){message.textContent=error.message}};
  const message=$('#person-scope-message');
  const post=async(url,body)=>{await operatorRequest(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});await loadCase(caseId)};
  $('#person-scope-form').onsubmit=async event=>{event.preventDefault();const f=Object.fromEntries(new FormData(event.currentTarget));try{await post(`/api/cases/${encodeURIComponent(caseId)}/person-scopes`,{...f,expiresAt:new Date(f.expiresAt).toISOString()})}catch(error){message.textContent=error.message}};
  detail.querySelectorAll('[data-scope-review]').forEach(button=>button.onclick=async()=>{const f=button.closest('.review-form');try{await post(`/api/person-scopes/${encodeURIComponent(button.dataset.scopeReview)}/review`,{decision:f.querySelector('select').value,rationale:f.querySelector('textarea').value})}catch(error){message.textContent=error.message}});
  detail.querySelectorAll('[data-person-review]').forEach(button=>button.onclick=async()=>{const f=button.closest('.review-form');try{await post(`/api/protected-people/${encodeURIComponent(button.dataset.personReview)}/review`,{decision:f.querySelector('select').value,rationale:f.querySelector('textarea').value})}catch(error){message.textContent=error.message}});
  detail.querySelectorAll('[data-person-scope]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const f=Object.fromEntries(new FormData(form)),scope=scopes.find(s=>s.id===form.dataset.personScope);try{await post(`/api/person-scopes/${encodeURIComponent(scope.id)}/people`,{displayName:f.displayName,role:scope.role,professionalRole:f.professionalRole,designationSource:{url:f.designationUrl,authority:f.designationAuthority,observedAt:new Date(f.designationObservedAt).toISOString()},identityConfidence:f.identityConfidence,identityRationale:f.identityRationale,publicProfessionalFacts:[{claim:f.factClaim,sourceUrl:f.factUrl,observedAt:new Date(f.factObservedAt).toISOString()}],retentionUntil:new Date(f.retentionUntil).toISOString()})}catch(error){message.textContent=error.message}});
}
function renderBriefSnapshots(caseId,caseRecord,items){
  if(caseRecord.subject.type!=='published_event')return;
  const detail=$('#case-detail');
  detail.insertAdjacentHTML('beforeend',`<section class="assessment-record"><h3>Saved brief versions</h3><p>Each version freezes its case content and source state for a separate internal review. Earlier versions remain available with their content hash; acceptance does not authorize operational use or onward sharing.</p><button id="save-brief-snapshot" type="button">Save a new brief version for review</button><p id="brief-snapshot-message"></p>${items.length?items.map((item,index)=>`<div class="feed-item"><strong>Version ${item.sequence} · ${esc(item.status.replaceAll('_',' '))}${index===0?' · latest':''}</strong><small>${fmt(item.createdAt)} · ${esc(item.createdBy)} · SHA-256 ${esc(item.contentHash)}</small>${item.review?`<p>Reviewer ${esc(item.review.reviewerId)}: ${esc(item.review.rationale)}</p>`:''}<button type="button" data-brief-download="${esc(item.id)}">Download this saved version</button>${currentOperator?.role==='reviewer'&&index===0&&item.status==='pending_review'&&item.createdBy!==currentOperator.id?`<div class="review-form"><select aria-label="Brief review decision"><option value="accepted_for_internal_review">Accept for internal review</option><option value="returned_for_correction">Return for correction</option></select><textarea aria-label="Brief review rationale" minlength="20" maxlength="2000" placeholder="Explain source and evidence checks"></textarea><button type="button" data-brief-review="${esc(item.id)}">Record brief decision</button></div>`:''}</div>`).join(''):'<p>No saved brief versions.</p>'}</section>`);
  const message=$('#brief-snapshot-message');
  $('#save-brief-snapshot').onclick=async()=>{message.textContent='Gathering current public context and saving version…';try{await operatorRequest(`/api/cases/${encodeURIComponent(caseId)}/brief-snapshots`,{method:'POST'});await loadCase(caseId)}catch(error){message.textContent=error.message}};
  detail.querySelectorAll('[data-brief-download]').forEach(button=>button.onclick=async()=>{try{const saved=await operatorRequest(`/api/brief-snapshots/${encodeURIComponent(button.dataset.briefDownload)}`),blob=new Blob([JSON.stringify(saved,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`event-atlas-case-${caseId}-brief-v${saved.sequence}.json`;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);message.textContent='Saved internal brief version downloaded locally.'}catch(error){message.textContent=error.message}});
  detail.querySelectorAll('[data-brief-review]').forEach(button=>button.onclick=async()=>{const form=button.closest('.review-form');try{await operatorRequest(`/api/brief-snapshots/${encodeURIComponent(button.dataset.briefReview)}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision:form.querySelector('select').value,rationale:form.querySelector('textarea').value})});await loadCase(caseId)}catch(error){message.textContent=error.message}});
}
async function loadCase(id){selectedCaseId=id;try{const d=await operatorRequest('/api/cases/'+encodeURIComponent(id)),c=d.case;$('#case-detail').innerHTML=`<span class="section-kicker">INTERNAL CASE · ${esc(c.id)}</span><h3>${esc(c.subject.title)}</h3><p>${esc(c.subject.type.replaceAll('_',' '))} · ${esc(c.authority)} · Opened ${fmt(c.createdAt)} by ${esc(c.createdBy)}</p><p><strong>Protective purpose:</strong> ${esc(c.purpose)}</p><p><strong>Opening rationale:</strong> ${esc(c.openingRationale)}</p><p>Source snapshot: ${link(c.subject.sourceUrl,'Publisher record')} · Retrieved ${fmt(c.subject.retrievedAt)}. Connector at intake: ${esc(c.subject.connectorStatus||'unknown')} · Record status: ${esc(c.subject.sourceStatus||c.subject.sourceDataStatus||'not supplied')}. Verify current status before protective action.</p>${d.sourceDrift?`<div class="source-note"><strong>Current local source comparison:</strong> ${esc(d.sourceDrift.status.replaceAll('_',' '))} · Connector ${esc(d.sourceDrift.connectorStatus)} · Latest record retrieved ${fmt(d.sourceDrift.latestRetrievedAt)}${d.sourceDrift.changedFields.length?' · Changed fields: '+esc(d.sourceDrift.changedFields.join(', ')):''}. For event cases, a missing listing does not establish cancellation. This comparison does not verify current field operation.</div>`:''}<h3>Assessment history</h3>${d.assessments.length?d.assessments.map(a=>`<div class="assessment-record"><span class="chip">${esc(a.status.replaceAll('_',' ').toUpperCase())}</span><strong>${esc(a.severity)} severity · ${esc(a.confidence)} confidence</strong><p>${esc(a.analysis)}</p><p><strong>Protective nexus:</strong> ${esc(a.protectiveNexus)}<br><strong>Potential impact:</strong> ${esc(a.impact)}<br><strong>Alternative explanations:</strong> ${esc(a.alternativeExplanations)}<br><strong>Confidence basis:</strong> ${esc(a.confidenceRationale)}<br><strong>Limitations:</strong> ${esc(a.limitations)}<br><strong>Proposed action:</strong> ${esc(a.recommendation)}</p><p>${a.evidence.length} analyst-entered citations · Internal only · No automatic notification</p>${a.evidence.map(x=>`<div class="feed-item"><strong>${esc(x.classification)} · ${esc(x.claim)}</strong><small>${fmt(x.observedAt)} · ${esc(x.relevance)} · ${link(x.url,'Source')}</small></div>`).join('')}${a.review?`<p>Reviewer ${esc(a.review.reviewerId)}: ${esc(a.review.decision.replaceAll('_',' '))} · ${esc(a.review.rationale)}</p>`:''}${currentOperator?.role==='reviewer'&&a.status==='pending_review'&&a.createdBy!==currentOperator.id?`<div class="review-form"><select aria-label="Assessment review decision"><option value="accepted_for_internal_review">Accept for internal review</option><option value="returned_for_correction">Return for correction</option></select><textarea aria-label="Assessment review rationale" placeholder="Review rationale (at least 20 characters)" maxlength="2000"></textarea><button class="primary" data-assessment-review="${esc(a.id)}" type="button">Record review</button></div>`:''}</div>`).join(''):'<p>No assessments yet.</p>'}<h3>Propose an assessment</h3><p>Analyst-entered evidence and judgments are pending human review. Adding an assessment does not notify anyone.</p><form id="assessment-form" class="assessment-form"><label>Proposed severity<select name="severity"><option value="informational">Informational context</option><option value="review_candidate">Review candidate</option><option value="actionable_concern">Actionable concern</option><option value="urgent_concern">Urgent concern</option></select></label><label>Evidence confidence<select name="confidence"><option value="low">Low</option><option value="moderate">Moderate</option><option value="high">High</option></select></label><label>Analysis<textarea name="analysis" required minlength="50" maxlength="5000"></textarea></label><label>Confidence basis<textarea name="confidenceRationale" required minlength="20" maxlength="2000"></textarea></label><label>Potential impact<textarea name="impact" required minlength="20" maxlength="2000"></textarea></label><label>Alternative explanations<textarea name="alternativeExplanations" required minlength="20" maxlength="2000"></textarea></label><label>Protective nexus<textarea name="protectiveNexus" required minlength="20" maxlength="2000"></textarea></label><label>Proposed action<textarea name="recommendation" required minlength="10" maxlength="2000"></textarea></label><label>Limitations and unknowns<textarea name="limitations" required minlength="20" maxlength="2000"></textarea></label><h3>Cited claims</h3><div id="assessment-evidence">${evidenceFields()}</div><button id="add-assessment-evidence" type="button">Add citation</button><button class="primary" type="submit">Save pending assessment</button><p id="assessment-message"></p></form>`;
renderCaseReviewers(id,c,d.reviewers||[]);renderPersonScopes(id,c,d.personScopes||[]);renderBriefSnapshots(id,c,d.briefSnapshots||[]);$('#add-assessment-evidence').onclick=()=>{if($('#assessment-evidence').children.length<20)$('#assessment-evidence').insertAdjacentHTML('beforeend',evidenceFields())};$('#assessment-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,input=Object.fromEntries(new FormData(form));delete input.url;delete input.observedAt;delete input.classification;delete input.claim;delete input.relevance;try{input.evidence=[...form.querySelectorAll('.evidence-entry')].map(row=>({url:row.querySelector('[name=url]').value,observedAt:new Date(row.querySelector('[name=observedAt]').value).toISOString(),classification:row.querySelector('[name=classification]').value,claim:row.querySelector('[name=claim]').value,relevance:row.querySelector('[name=relevance]').value}));await operatorRequest(`/api/cases/${encodeURIComponent(id)}/assessments`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});await loadCase(id)}catch(error){$('#assessment-message').textContent=error.message}};document.querySelectorAll('[data-assessment-review]').forEach(button=>button.onclick=async()=>{const section=button.closest('.review-form');try{await operatorRequest(`/api/assessments/${encodeURIComponent(button.dataset.assessmentReview)}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision:section.querySelector('select').value,rationale:section.querySelector('textarea').value})});await loadCase(id)}catch(error){$('#assessment-message').textContent=error.message}})}catch(error){$('#case-detail').textContent='Case unavailable: '+error.message}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-case-type][data-case-id]');if(!button)return;view('cases');$('#case-form [name=subjectType]').value=button.dataset.caseType;$('#case-form [name=subjectId]').value=button.dataset.caseId;$('#case-message').textContent='Source record selected. Enter the protective purpose and responsible authority before opening a case.'});
for(const b of document.querySelectorAll('.rail-item'))b.onclick=()=>view(b.dataset.view);$('#map-expand').onclick=()=>view('venues');$('#search-button').onclick=()=>search(true);$('#prev-page').onclick=()=>{offset=Math.max(0,offset-100);search()};$('#next-page').onclick=()=>{offset+=100;search()};$('#venue-search').onkeydown=e=>{if(e.key==='Enter')search(true)};$('#venue-type').onchange=()=>search(true);$('#published-search-button').onclick=()=>loadPublished(true);$('#published-source').onchange=()=>loadPublished(true);$('#published-search').onkeydown=e=>{if(e.key==='Enter')loadPublished(true)};$('#published-prev').onclick=()=>{publishedOffset=Math.max(0,publishedOffset-50);loadPublished()};$('#published-next').onclick=()=>{publishedOffset+=50;loadPublished()};$('#voting-search-button').onclick=()=>loadVoting(true);$('#voting-state').onchange=()=>loadVoting(true);$('#voting-type').onchange=()=>loadVoting(true);$('#voting-search').onkeydown=e=>{if(e.key==='Enter')loadVoting(true)};$('#voting-prev').onclick=()=>{votingOffset=Math.max(0,votingOffset-50);loadVoting()};$('#voting-next').onclick=()=>{votingOffset+=50;loadVoting()};$('#clock').textContent=new Date().toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});init();
